template <typename T>
void Swap(T& a, T& b) {
    T temp = a;
    a = b;
    b = temp;
}

// Template with multiple types
template <typename T1, typename T2>
auto Max(T1 a, T2 b) {
    return (a > b) ? a : b;
}

// Explicit specialization syntax
template <>
const char* Max<const char*>(const char* a, const char* b);

// Explicit Instantiation (forces compilation for specific type)
template void Swap<int>(int&, int&);
